import esbuild from 'esbuild';
import fs from 'node:fs';
import { parseArgs } from 'node:util';
import envs from './envs.js';
import browserslistToEsbuild from 'browserslist-to-esbuild';

let args = parseArgs({options: {
  watch: { type: 'boolean' },
  stats: { type: 'boolean' },
  // the desktop app bundles the editor with relative data URLs into its own
  // directory, so the website bundle in dist/ is left alone
  outfile: { type: 'string' }
}}).values;

const build = await esbuild.build({
  define: envs,
  minify: true,
  bundle: true,
  sourcemap: true,
  entryPoints: ['./modules/id.js'],
  legalComments: 'none',
  logLevel: 'info',
  metafile: true,
  outfile: args.outfile || 'dist/iD.min.js',
  target: browserslistToEsbuild(),
  loader: { '.DS_Store' : 'empty' },
  treeShaking: true,
})
.catch(() => process.exit(1));

if (args.stats) {
  fs.writeFileSync('./dist/esbuild.json', JSON.stringify(build.metafile, null, 2));
}
